#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

readonly REGION="asia-east1"
readonly SERVICE="rent-poc-demo"
readonly AR_REPOSITORY="rent-poc"
readonly WIF_POOL="github"
readonly WIF_PROVIDER_ID="rent-poc"
readonly DEPLOY_SA_NAME="rent-poc-deployer"
readonly RUNTIME_SA_NAME="rent-poc-runtime"
readonly WORKFLOW="ci-deploy.yml"

# create_if_missing "描述" "檢查指令" "建立指令"：重跑時略過已存在的資源
create_if_missing() {
  local description="$1" check="$2" create="$3"
  if eval "$check" >/dev/null 2>&1; then
    printf '  %s✓ 已存在%s %s\n' "$GREEN" "$RESET" "$description"
  else
    eval "$create" >/dev/null
    printf '  %s✓ 已建立%s %s\n' "$GREEN" "$RESET" "$description"
  fi
}

# grant_quiet：加 IAM 綁定，不把整份 policy 印到畫面
grant_quiet() {
  "$@" --quiet >/dev/null
}

# store_secret NAME VALUE：新增 Secret Manager 的版本，並讓 runtime service account 能讀
store_secret() {
  local name="$1" value="$2"
  if ! gcloud secrets describe "$name" >/dev/null 2>&1; then
    gcloud secrets create "$name" --replication-policy=user-managed --locations="$REGION" --quiet >/dev/null
  fi
  printf '%s' "$value" | gcloud secrets versions add "$name" --data-file=- --quiet >/dev/null
  grant_quiet gcloud secrets add-iam-policy-binding "$name" \
    --member="serviceAccount:${RUNTIME_SA}" --role=roles/secretmanager.secretAccessor
  printf '  %s✓ 已存入%s Secret Manager：%s\n' "$GREEN" "$RESET" "$name"
}

# run_deploy：手動觸發一次 workflow，並等它結束
run_deploy() {
  local before run_id="" attempt
  before=$(latest_dispatch_run)
  gh workflow run "$WORKFLOW" --ref main
  say "等待 GitHub 建立這次執行。"
  for attempt in $(seq 1 30); do
    run_id=$(latest_dispatch_run)
    [[ -n "$run_id" && "$run_id" != "$before" ]] && break
    run_id=""
    sleep 3
  done
  if [[ -z "$run_id" ]]; then
    warn "等了 90 秒還看不到新的執行。請到 GitHub Actions 頁面查看。"
    return 1
  fi
  gh run watch "$run_id" --exit-status
}

latest_dispatch_run() {
  gh run list --workflow "$WORKFLOW" --event workflow_dispatch --limit 1 --json databaseId --jq '.[0].databaseId // ""'
}

# ask_required_secret KEY "Prompt"：空白輸入要重問，避免把空字串存進 Secret Manager
ask_required_secret() {
  local key="$1" prompt="$2"
  ask_secret "$key" "$prompt"
  until [[ -n "${!key}" ]]; do
    warn "不能是空白。"
    ask_secret "$key" "$prompt"
  done
}

run_wizard() {

# 從 repo 根目錄執行，gh 才找得到 repo。設定值存在 .env.deploy（已被 .gitignore 排除），重跑時沿用。
cd "$(dirname "$0")/.."
ENV_FILE=".env.deploy"

TOTAL_STAGES=11

banner "rent-poc：第一次部署到 Cloud Run"

stage "安裝並登入 gcloud 與 gh"
say "這個腳本不會把任何憑證傳給 AI。登入都在你自己的瀏覽器完成。"
if ! command -v gcloud >/dev/null 2>&1; then
  if confirm "沒有找到 gcloud。要用 Homebrew 安裝嗎？"; then
    brew install --cask gcloud-cli
    warn "如果下一行找不到 gcloud，開新的終端機再重跑這個腳本。"
  else
    warn "請先安裝 gcloud：https://cloud.google.com/sdk/docs/install"
    exit 1
  fi
fi
command -v gcloud >/dev/null 2>&1 || exit 1
gcloud auth list --filter=status:ACTIVE --format='value(account)' | grep -q . || gcloud auth login
note "目前的 Google 帳號：$(gcloud auth list --filter=status:ACTIVE --format='value(account)')"
gh auth status >/dev/null 2>&1 || gh auth login
note "目前的 repo：$(gh repo view --json nameWithOwner --jq .nameWithOwner)"
pause "確認帳號與 repo 正確後，按 Enter。"

stage "建立 GCP 專案並連結帳單"
warn "連結帳單需要信用卡。新帳號有 US\$300 試用額度，效期 90 天。"
note "預估月費約 US\$0.4，整月 min-instances=1 時約 US\$48。"
say "專案 ID 全球唯一，只能用小寫英文、數字與連字號，例如 rent-poc-demo-7421。"
ask GCP_PROJECT_ID "輸入專案 ID："
write_env GCP_PROJECT_ID "$GCP_PROJECT_ID"
create_if_missing "專案 $GCP_PROJECT_ID" \
  "gcloud projects describe '$GCP_PROJECT_ID'" \
  "gcloud projects create '$GCP_PROJECT_ID'"
gcloud config set project "$GCP_PROJECT_ID" --quiet >/dev/null 2>&1
# gcloud 可能把這個專案當 quota project，帳單 API 沒有啟用時，下面的檢查會一直失敗
gcloud services enable cloudbilling.googleapis.com --quiet >/dev/null 2>&1 || true
open_url "https://console.cloud.google.com/billing/linkedaccount?project=${GCP_PROJECT_ID}"
step "在這個頁面把專案連結到帳單帳戶。沒有帳單帳戶時，先照畫面建立一個。"
until [[ "$(gcloud billing projects describe "$GCP_PROJECT_ID" --format='value(billingEnabled)')" == "True" ]]; do
  pause "完成帳單連結後，按 Enter 重新檢查。"
done
GCP_PROJECT_NUMBER=$(gcloud projects describe "$GCP_PROJECT_ID" --format='value(projectNumber)')
write_env GCP_PROJECT_NUMBER "$GCP_PROJECT_NUMBER"
APP_ORIGIN="https://${SERVICE}-${GCP_PROJECT_NUMBER}.${REGION}.run.app"
pause "按 Enter 繼續。"

stage "啟用 API 並設定預算警示"
say "啟用 API 約需 1 分鐘。"
gcloud services enable \
  run.googleapis.com artifactregistry.googleapis.com secretmanager.googleapis.com \
  storage.googleapis.com iam.googleapis.com iamcredentials.googleapis.com sts.googleapis.com \
  cloudresourcemanager.googleapis.com billingbudgets.googleapis.com
printf '  %s✓ API 已啟用%s\n' "$GREEN" "$RESET"
BILLING_ACCOUNT=$(gcloud billing projects describe "$GCP_PROJECT_ID" --format='value(billingAccountName)')
BILLING_ACCOUNT_ID="${BILLING_ACCOUNT#billingAccounts/}"
if gcloud billing budgets list --billing-account="$BILLING_ACCOUNT_ID" --format='value(displayName)' 2>/dev/null | grep -qx 'rent-poc-demo'; then
  printf '  %s✓ 已存在%s 預算 rent-poc-demo\n' "$GREEN" "$RESET"
elif gcloud billing budgets create --billing-account="$BILLING_ACCOUNT_ID" \
    --display-name='rent-poc-demo' --budget-amount=5USD \
    --filter-projects="projects/${GCP_PROJECT_NUMBER}" \
    --threshold-rule=percent=0.5 --threshold-rule=percent=1.0 >/dev/null 2>&1; then
  printf '  %s✓ 已建立%s US$5 預算警示\n' "$GREEN" "$RESET"
else
  SKIPPED+=("US\$5 預算警示：到 Billing → Budgets & alerts 手動建立")
  warn "無法用指令建立預算。結束後請手動建立：https://console.cloud.google.com/billing/budgets"
fi
note "預算只寄警示，不會停止服務。花費上限靠 max-instances=1。"
pause "按 Enter 繼續。"

stage "建立 Artifact Registry 與 Cloud Storage bucket"
create_if_missing "Artifact Registry $AR_REPOSITORY" \
  "gcloud artifacts repositories describe '$AR_REPOSITORY' --location='$REGION'" \
  "gcloud artifacts repositories create '$AR_REPOSITORY' --repository-format=docker --location='$REGION' --quiet"
CLEANUP_POLICY=$(mktemp)
cat > "$CLEANUP_POLICY" <<'POLICY'
[
  {"name": "keep-recent", "action": {"type": "Keep"}, "mostRecentVersions": {"keepCount": 3}},
  {"name": "delete-rest", "action": {"type": "Delete"}, "condition": {"tagState": "any"}}
]
POLICY
gcloud artifacts repositories set-cleanup-policies "$AR_REPOSITORY" --location="$REGION" \
  --policy="$CLEANUP_POLICY" --no-dry-run --quiet >/dev/null
rm -f "$CLEANUP_POLICY"
note "映像只保留最近 3 個版本，費用維持在免費額度附近。"
LITESTREAM_BUCKET="${GCP_PROJECT_ID}-demo-db"
create_if_missing "bucket gs://$LITESTREAM_BUCKET" \
  "gcloud storage buckets describe 'gs://$LITESTREAM_BUCKET'" \
  "gcloud storage buckets create 'gs://$LITESTREAM_BUCKET' --location='$REGION' --uniform-bucket-level-access --public-access-prevention --quiet"
write_env LITESTREAM_BUCKET "$LITESTREAM_BUCKET"
pause "按 Enter 繼續。"

stage "建立 service account 並授權"
DEPLOY_SA="${DEPLOY_SA_NAME}@${GCP_PROJECT_ID}.iam.gserviceaccount.com"
RUNTIME_SA="${RUNTIME_SA_NAME}@${GCP_PROJECT_ID}.iam.gserviceaccount.com"
create_if_missing "部署用 $DEPLOY_SA_NAME" \
  "gcloud iam service-accounts describe '$DEPLOY_SA'" \
  "gcloud iam service-accounts create '$DEPLOY_SA_NAME' --display-name='GitHub Actions deployer' --quiet"
create_if_missing "執行用 $RUNTIME_SA_NAME" \
  "gcloud iam service-accounts describe '$RUNTIME_SA'" \
  "gcloud iam service-accounts create '$RUNTIME_SA_NAME' --display-name='Cloud Run runtime' --quiet"
say "等待新的 service account 生效（15 秒）。"
sleep 15
grant_quiet gcloud projects add-iam-policy-binding "$GCP_PROJECT_ID" \
  --member="serviceAccount:${DEPLOY_SA}" --role=roles/run.admin
gcloud artifacts repositories add-iam-policy-binding "$AR_REPOSITORY" --location="$REGION" \
  --member="serviceAccount:${DEPLOY_SA}" --role=roles/artifactregistry.writer --quiet >/dev/null
gcloud iam service-accounts add-iam-policy-binding "$RUNTIME_SA" \
  --member="serviceAccount:${DEPLOY_SA}" --role=roles/iam.serviceAccountUser --quiet >/dev/null
gcloud storage buckets add-iam-policy-binding "gs://${LITESTREAM_BUCKET}" \
  --member="serviceAccount:${RUNTIME_SA}" --role=roles/storage.admin --quiet >/dev/null
write_env DEPLOY_SA "$DEPLOY_SA"
write_env RUNTIME_SA "$RUNTIME_SA"
note "部署用：只能部署 Cloud Run、推映像、以執行用身分啟動服務。"
note "執行用：只能存取這個 bucket 與指定的 secrets。"
pause "按 Enter 繼續。"

stage "設定 Workload Identity Federation"
say "GitHub Actions 用短期 token 登入 GCP，repo 內不存金鑰。只有這個 repo 的 main 分支能部署。"
GITHUB_REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner)
GITHUB_REPO_ID=$(gh api "repos/${GITHUB_REPO}" --jq .id)
GITHUB_OWNER_ID=$(gh api "repos/${GITHUB_REPO}" --jq .owner.id)
create_if_missing "workload identity pool $WIF_POOL" \
  "gcloud iam workload-identity-pools describe '$WIF_POOL' --location=global" \
  "gcloud iam workload-identity-pools create '$WIF_POOL' --location=global --display-name='GitHub Actions' --quiet"
create_if_missing "provider $WIF_PROVIDER_ID" \
  "gcloud iam workload-identity-pools providers describe '$WIF_PROVIDER_ID' --location=global --workload-identity-pool='$WIF_POOL'" \
  "gcloud iam workload-identity-pools providers create-oidc '$WIF_PROVIDER_ID' --location=global --workload-identity-pool='$WIF_POOL' --issuer-uri='https://token.actions.githubusercontent.com' --attribute-mapping='google.subject=assertion.sub,attribute.repository_id=assertion.repository_id,attribute.repository_owner_id=assertion.repository_owner_id,attribute.ref=assertion.ref' --attribute-condition=\"assertion.repository_id=='${GITHUB_REPO_ID}' && assertion.repository_owner_id=='${GITHUB_OWNER_ID}' && assertion.ref=='refs/heads/main'\" --quiet"
gcloud iam service-accounts add-iam-policy-binding "$DEPLOY_SA" --role=roles/iam.workloadIdentityUser \
  --member="principalSet://iam.googleapis.com/projects/${GCP_PROJECT_NUMBER}/locations/global/workloadIdentityPools/${WIF_POOL}/attribute.repository_id/${GITHUB_REPO_ID}" \
  --quiet >/dev/null
WIF_PROVIDER=$(gcloud iam workload-identity-pools providers describe "$WIF_PROVIDER_ID" --location=global \
  --workload-identity-pool="$WIF_POOL" --format='value(name)')
write_env WIF_PROVIDER "$WIF_PROVIDER"
pause "按 Enter 繼續。"

stage "產生 demo 的 Basic Auth 密碼"
if gcloud secrets versions access latest --secret=demo-basic-auth-password >/dev/null 2>&1 \
    && ! confirm "密碼已存在。要換一組新密碼嗎？"; then
  note "沿用現有密碼。"
else
  DEMO_PASSWORD=$(openssl rand -base64 18)
  store_secret demo-basic-auth-password "$DEMO_PASSWORD"
  say "帳號：demo"
  say "密碼：$DEMO_PASSWORD"
  warn "這組密碼只顯示這一次。請存到你的密碼管理工具。"
  unset DEMO_PASSWORD
fi
pause "存好密碼後，按 Enter。畫面與捲動紀錄都會清除。"
printf '\033[3J'

stage "寫入 GitHub repo variables"
say "這些都不是機密。repo 是 public，執行紀錄裡看得到。機密都放在 Secret Manager。"
set_var GCP_PROJECT_ID "$GCP_PROJECT_ID"
set_var GCP_PROJECT_NUMBER "$GCP_PROJECT_NUMBER"
set_var WIF_PROVIDER "$WIF_PROVIDER"
set_var DEPLOY_SA "$DEPLOY_SA"
set_var RUNTIME_SA "$RUNTIME_SA"
set_var LITESTREAM_BUCKET "$LITESTREAM_BUCKET"
if [[ -z "$(gh variable get DOTTEDSIGN_ENABLED 2>/dev/null || true)" ]]; then
  set_var DOTTEDSIGN_ENABLED "false"
fi
pause "按 Enter 繼續。"

stage "第一次部署（mock 模式）"
say "點點簽的後台在儲存 webhook URL 時會打這個網址，所以服務要先上線。"
until gh api "repos/${GITHUB_REPO}/contents/.github/workflows/${WORKFLOW}?ref=main" >/dev/null 2>&1; do
  warn "origin/main 還沒有 .github/workflows/${WORKFLOW}。"
  step "把部署分支合併到 main，然後 push 到 origin。"
  pause "push 之後，按 Enter 重新檢查。"
done
say "push main 已經觸發過 workflow 時，那次也可能在部署。這裡再手動跑一次，確保設定都生效。"
run_deploy
curl --fail --silent --show-error --retry 5 --retry-delay 5 "${APP_ORIGIN}/api/health" >/dev/null
printf '  %s✓ 健康檢查通過%s %s\n' "$GREEN" "$RESET" "$APP_ORIGIN"
open_url "$APP_ORIGIN"
step "在瀏覽器輸入帳號 demo 與剛才的密碼，確認看得到系統畫面。"
pause "看到畫面後，按 Enter。"

stage "建立點點簽 demo Application"
warn "不要改原本的 Application。它的 webhook 還要給本機 ngrok 用。"
open_url "https://developer.dottedsign.com/"
step "登入 sandbox 開發者後台，建立一個新的 Application，名稱建議 rent-poc-demo。"
step "Webhook URL 填：${APP_ORIGIN}/api/webhooks/dottedsign"
step "scope 勾選：sign_tasks.general.write、sign_tasks.general.read、sign_tasks.management.write、sign_tasks.download.read"
note "實際按鈕與欄位名稱以後台畫面為準，這份腳本沒有逐一核對畫面。"
note "儲存時後台會打一次 webhook URL，服務會回 200。"
if gcloud secrets versions access latest --secret=dottedsign-client-secret >/dev/null 2>&1 \
    && ! confirm "點點簽金鑰已存在。要重新輸入嗎？"; then
  note "沿用現有的點點簽金鑰。"
else
  ask_required_secret DOTTEDSIGN_CLIENT_ID "貼上 client id（輸入不會顯示）："
  ask_required_secret DOTTEDSIGN_CLIENT_SECRET "貼上 client secret（輸入不會顯示）："
  store_secret dottedsign-client-id "$DOTTEDSIGN_CLIENT_ID"
  store_secret dottedsign-client-secret "$DOTTEDSIGN_CLIENT_SECRET"
  unset DOTTEDSIGN_CLIENT_ID DOTTEDSIGN_CLIENT_SECRET
fi
set_var DOTTEDSIGN_ENABLED "true"
pause "按 Enter 繼續。"

stage "重新部署並驗收"
run_deploy
open_url "${APP_ORIGIN}/api/meta"
step "確認這一頁顯示 \"mock\":false。"
open_url "$APP_ORIGIN"
step "建立一個物件與一張合約，甲乙雙方都填你自己的信箱，只用測試資料。"
step "送簽後從點點簽系統內開啟任務並簽署。sandbox 不寄邀請信。"
step "確認合約頁的狀態有跟著變，這代表 webhook 通了。"
pause "驗收完成後，按 Enter。"

finish
say "demo 網址：$APP_ORIGIN"
say "日常操作（demo 當天保持開機、回滾、換密碼）見 docs/deployment.md。"
printf '\n'
}

run_wizard "$@"; exit
